// BackOfficeLabs — LEDGER full home page (responsive).
// Aesthetic: clean / premium / corporate. Tone: professional & trustworthy.
const { useState, useRef, useEffect } = React;

const LA = {
  ink: "#1B1E2B",
  paper: "#FBFAF8",
  white: "#FFFFFF",
  accent: "oklch(0.52 0.16 268)",
  accentSoft: "oklch(0.96 0.025 268)",
  line: "rgba(27,30,43,0.12)",
  muted: "rgba(27,30,43,0.62)",
  danger: "oklch(0.55 0.18 25)"
};

function LaPlaceholder({ label, h = 240, style = {} }) {
  return (
    <div style={{ height: h, borderRadius: 12, border: `1px solid ${LA.line}`, background: "repeating-linear-gradient(45deg,#F4F3F0,#F4F3F0 9px,#EFEEEA 9px,#EFEEEA 18px)", display: "flex", alignItems: "center", justifyContent: "center", ...style }}>
      <span style={{ fontFamily: "monospace", fontSize: 12.5, color: "rgba(27,30,43,0.42)", background: LA.paper, padding: "4px 10px", borderRadius: 6, border: `1px solid ${LA.line}` }}>{label}</span>
    </div>);

}

function LaSectionLabel({ n, children }) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 18 }}>
      <span style={{ fontFamily: "monospace", fontSize: 13, color: LA.accent, fontWeight: 600 }}>{n}</span>
      <span style={{ width: 28, height: 1, background: LA.line }} />
      <span style={{ fontSize: 14, fontWeight: 600, letterSpacing: "0.06em", textTransform: "uppercase", color: LA.muted }}>{children}</span>
    </div>);

}

function LaSectionLabelDark({ n, children }) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 18 }}>
      <span style={{ fontFamily: "monospace", fontSize: 13, color: "oklch(0.8 0.1 268)", fontWeight: 600 }}>{n}</span>
      <span style={{ width: 28, height: 1, background: "rgba(251,250,248,0.25)" }} />
      <span style={{ fontSize: 14, fontWeight: 600, letterSpacing: "0.06em", textTransform: "uppercase", color: "rgba(251,250,248,0.6)" }}>{children}</span>
    </div>);

}

function LedgerNav() {
  const [open, setOpen] = useState(false);
  const links = [["What we build", "#tracks"], ["The Audit", "#audit"], ["How we work", "#process"], ["The Work", "#work"], ["Founders", "#founders"]];
  const close = () => setOpen(false);
  return (
    <header style={{ position: "sticky", top: 0, zIndex: 60, background: "rgba(251,250,248,0.85)", backdropFilter: "blur(12px)", borderBottom: `1px solid ${LA.line}` }}>
      <nav className="la-container" style={{ display: "flex", alignItems: "center", justifyContent: "space-between", paddingTop: 16, paddingBottom: 16 }}>
        <a href="#top" onClick={close} className="la-btn" style={{ gap: 10 }}>
          <span style={{ width: 26, height: 26, borderRadius: 6, background: LA.ink, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
            <span style={{ width: 11, height: 11, borderRadius: 3, border: `2px solid ${LA.paper}` }} />
          </span>
          <span className="la-serif" style={{ fontSize: 20, fontWeight: 600, letterSpacing: "-0.01em", color: LA.ink }}>BackOffice<span style={{ color: LA.accent }}>Labs</span></span>
        </a>
        <div className="la-navlinks" style={{ alignItems: "center", gap: 30 }}>
          {links.map(([t, h]) => <a key={t} className="la-link" href={h}>{t}</a>)}
        </div>
        <a href="#contact" className="la-btn la-nav-cta" style={{ background: LA.ink, color: LA.paper, fontSize: 15, fontWeight: 600, padding: "11px 20px", borderRadius: 8 }}>Book the audit</a>
        <button aria-label="Menu" className="la-burger" onClick={() => setOpen((o) => !o)} style={{ background: "none", border: `1px solid ${LA.line}`, borderRadius: 8, width: 42, height: 42, cursor: "pointer", flexDirection: "column", gap: 4, justifyContent: "center", alignItems: "center", padding: 0 }}>
          <span style={{ width: 18, height: 2, background: LA.ink, borderRadius: 2, transition: "transform .2s", transform: open ? "translateY(6px) rotate(45deg)" : "none" }} />
          <span style={{ width: 18, height: 2, background: LA.ink, borderRadius: 2, opacity: open ? 0 : 1, transition: "opacity .2s" }} />
          <span style={{ width: 18, height: 2, background: LA.ink, borderRadius: 2, transition: "transform .2s", transform: open ? "translateY(-6px) rotate(-45deg)" : "none" }} />
        </button>
      </nav>
      {open &&
      <div className="la-mobile-menu" style={{ borderTop: `1px solid ${LA.line}`, background: LA.paper, padding: "10px clamp(20px,5vw,40px) 22px", display: "flex", flexDirection: "column", gap: 4 }}>
          {links.map(([t, h]) => <a key={t} href={h} onClick={close} style={{ textDecoration: "none", color: LA.ink, fontSize: 18, fontWeight: 600, padding: "13px 0", borderBottom: `1px solid ${LA.line}` }}>{t}</a>)}
          <a href="#contact" onClick={close} className="la-btn" style={{ justifyContent: "center", background: LA.ink, color: LA.paper, fontSize: 16, fontWeight: 600, padding: "14px", borderRadius: 9, marginTop: 12 }}>Book the audit</a>
        </div>
      }
    </header>);

}

function LedgerContactForm() {
  const [form, setForm] = useState({ name: "", email: "", company: "", note: "" });
  const [errors, setErrors] = useState({});
  const [sent, setSent] = useState(false);
  const set = (k) => (e) => setForm((f) => ({ ...f, [k]: e.target.value }));
  const submit = (e) => {
    e.preventDefault();
    const err = {};
    if (!form.name.trim()) err.name = "Please add your name.";
    if (!form.email.trim()) err.email = "Please add your email.";else
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email)) err.email = "That email doesn't look right.";
    if (!form.company.trim()) err.company = "Please add your company.";
    setErrors(err);
    if (Object.keys(err).length === 0) setSent(true);
  };
  const fieldStyle = (k) => ({ background: "rgba(251,250,248,0.06)", border: `1px solid ${errors[k] ? LA.danger : "rgba(251,250,248,0.2)"}`, borderRadius: 9, padding: "13px 14px", fontSize: 16, color: LA.paper, outline: "none", fontFamily: "inherit", width: "100%" });
  if (sent) {
    return (
      <div style={{ background: "rgba(251,250,248,0.05)", border: "1px solid rgba(251,250,248,0.16)", borderRadius: 16, padding: 36, display: "flex", flexDirection: "column", alignItems: "flex-start", gap: 14, minHeight: 280, justifyContent: "center" }}>
        <span style={{ width: 48, height: 48, borderRadius: 99, background: LA.accent, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 24, color: "#fff" }}>✓</span>
        <h3 className="la-serif" style={{ fontSize: 28, fontWeight: 500, margin: 0, color: LA.paper }}>Thanks, {form.name.split(" ")[0]}.</h3>
        <p style={{ fontSize: 16, lineHeight: 1.55, color: "rgba(251,250,248,0.7)", margin: 0 }}>We'll be in touch within one business day to set up your audit. No spam, no drip campaign — just us.</p>
        <button onClick={() => {setSent(false);setForm({ name: "", email: "", company: "", note: "" });}} className="la-btn" style={{ background: "transparent", color: LA.paper, border: "1px solid rgba(251,250,248,0.3)", fontSize: 14, fontWeight: 600, padding: "10px 16px", borderRadius: 8, cursor: "pointer", marginTop: 4 }}>Send another →</button>
      </div>);

  }
  return (
    <form onSubmit={submit} noValidate style={{ background: "rgba(251,250,248,0.05)", border: "1px solid rgba(251,250,248,0.16)", borderRadius: 16, padding: "clamp(22px,4vw,30px)", display: "flex", flexDirection: "column", gap: 14 }}>
      {[["name", "Name", "Jane Doe"], ["email", "Work email", "jane@company.com"], ["company", "Company", "Company Inc."]].map(([k, l, p]) =>
      <label key={k} style={{ display: "flex", flexDirection: "column", gap: 6, fontSize: 13.5, color: "rgba(251,250,248,0.7)" }}>
          {l}
          <input value={form[k]} onChange={set(k)} placeholder={p} style={fieldStyle(k)} />
          {errors[k] && <span style={{ fontSize: 12.5, color: "oklch(0.78 0.13 25)" }}>{errors[k]}</span>}
        </label>
      )}
      <label style={{ display: "flex", flexDirection: "column", gap: 6, fontSize: 13.5, color: "rgba(251,250,248,0.7)" }}>
        What would you point AI at first? <span style={{ opacity: 0.55 }}>(optional)</span>
        <textarea value={form.note} onChange={set("note")} rows={3} placeholder="e.g. one operating picture, lead response, getting found in search…" style={{ ...fieldStyle("note"), resize: "vertical", lineHeight: 1.5 }} />
      </label>
      <button type="submit" className="la-btn" style={{ justifyContent: "center", background: LA.paper, color: LA.ink, fontSize: 16, fontWeight: 700, padding: "15px", borderRadius: 9, border: "none", cursor: "pointer", marginTop: 4 }}>Book my audit →</button>
      <span style={{ fontSize: 12.5, color: "rgba(251,250,248,0.5)", textAlign: "center" }}>Written audit in 5 working days · from £750 · credited in full against any build</span>
    </form>);

}

function LedgerFaq() {
  const items = [
  ["Why fixed price? Everyone else bills hourly or monthly.", "Because AI-native delivery makes scope predictable for us — so the risk shouldn't sit with you. You know the full price before we start. If we over-deliver (we usually do), it's not billed."],
  ["What if the build doesn't pay back?", "Then we won't recommend it. The audit shows the payback number — in time, cost, or revenue — before any build is proposed, and includes what we're NOT recommending. If nothing pays back, the audit says so and you've spent £750 to avoid a £15k mistake."],
  ["Who owns the system afterwards?", "You do. Every engagement ends with a documented handover — architecture, workflows node-by-node, troubleshooting — so your team runs it in-house. No dependency on us by design."],
  ["Then what's the monthly retainer for?", "System Operations is optional and offered only at handover: monitoring, iteration, and new modules as you grow. Monthly, cancel any time — each month is a decision point, same as our build phases. It exists because systems compound when someone keeps improving them, not because you can't run yours."],
  ["You're fast and fixed-price. Is this AI slop?", "The opposite — verification is the product. Our systems check their own claims against the source of truth, integrations self-heal instead of duplicating, and every deliverable passes QA gates before you see it. Fast is a property of the delivery model, not of the quality bar."],
  ["Where are you based?", "London and India. Engagements are fronted from London; delivery runs on our systems and playbooks. It's part of how team-scale output ships at these prices."]];

  const [open, setOpen] = useState(0);
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 0, borderTop: `1px solid ${LA.line}` }}>
      {items.map(([q, a], i) => {
        const isOpen = open === i;
        return (
          <div key={q} style={{ borderBottom: `1px solid ${LA.line}` }}>
            <button onClick={() => setOpen(isOpen ? -1 : i)} style={{ width: "100%", display: "flex", alignItems: "center", gap: 18, background: "none", border: "none", cursor: "pointer", padding: "24px 4px", textAlign: "left", fontFamily: "inherit" }}>
              <span style={{ fontFamily: "monospace", fontSize: 13, color: LA.accent, fontWeight: 600, flexShrink: 0 }}>{String(i + 1).padStart(2, "0")}</span>
              <span style={{ fontSize: "clamp(17px,2vw,19px)", fontWeight: 600, color: LA.ink, letterSpacing: "-0.01em", flex: 1 }}>{q}</span>
              <span style={{ flexShrink: 0, width: 26, height: 26, borderRadius: 99, border: `1px solid ${LA.line}`, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 17, color: LA.accent, transition: "transform .25s", transform: isOpen ? "rotate(45deg)" : "none" }}>+</span>
            </button>
            <div style={{ overflow: "hidden", maxHeight: isOpen ? 520 : 0, opacity: isOpen ? 1 : 0, transition: "max-height .35s ease, opacity .3s ease" }}>
              <p style={{ fontSize: 16.5, lineHeight: 1.6, color: LA.muted, margin: 0, padding: "0 44px 26px 38px", maxWidth: 660 }}>{a}</p>
            </div>
          </div>);

      })}
    </div>);

}

function HeroCollapse() {
  const green = "oklch(0.6 0.13 155)";
  const chips = [
  ["Payments", -4], ["Spreadsheets", 18], ["Calendar", -10],
  ["Email platform", 12], ["Slack", -6], ["Database", 22]];

  const rows = [
  { t: "Customer 360°", s: "", tag: "risk 82 · never logged in", tone: "risk" },
  { t: "Refund saved", s: "", tag: "verified against source", tone: "ok" },
  { t: "Today's priorities → Slack", s: "", tag: "sent 09:00", tone: "mute" }];

  const wrapRef = useRef(null);
  const [flow, setFlow] = useState(null);
  useEffect(() => {
    const wrap = wrapRef.current;
    if (!wrap) return;
    const mq = window.matchMedia("(max-width: 640px)");
    const measure = () => {
      if (!mq.matches) {setFlow(null);return;}
      const chipEls = Array.from(wrap.querySelectorAll(".la-toolchip"));
      const panel = wrap.querySelector(".la-osurface");
      if (!chipEls.length || !panel) return;
      const cx = panel.offsetLeft + panel.offsetWidth / 2;
      const cy = panel.offsetTop;
      const pts = chipEls.map((el) => ({ x: el.offsetLeft + el.offsetWidth / 2, y: el.offsetTop + el.offsetHeight - 1 }));
      setFlow({ w: wrap.offsetWidth, h: wrap.offsetHeight, cx, cy, pts });
    };
    measure();
    const t1 = setTimeout(measure, 350);
    const t2 = setTimeout(measure, 1600);
    window.addEventListener("resize", measure);
    return () => {clearTimeout(t1);clearTimeout(t2);window.removeEventListener("resize", measure);};
  }, []);

  return (
    <div className="la-collapse" ref={wrapRef}>
      <div className="la-chipcol">
        {chips.map(([label, dx], i) =>
        <span key={label} className="la-toolchip" style={{ marginLeft: Math.max(0, dx), animationDelay: `${i * 0.12}s` }}>
            <span className="la-chipdot" />{label}
          </span>
        )}
      </div>
      <svg className="la-cvg" viewBox="0 0 60 260" preserveAspectRatio="none" aria-hidden="true">
        {[26, 74, 108, 150, 186, 232].map((y, i) =>
        <path key={i} d={`M0 ${y} C 34 ${y}, 30 130, 56 130`} fill="none" stroke="oklch(0.52 0.16 268 / 0.35)" strokeWidth="1.5" />
        )}
        <path d="M50 124 L60 130 L50 136 Z" fill="oklch(0.52 0.16 268)" />
      </svg>
      <div className="la-downarrow" aria-hidden="true"></div>
      {flow &&
      <svg className="la-flowm" width={flow.w} height={flow.h} viewBox={`0 0 ${flow.w} ${flow.h}`} aria-hidden="true">
          {flow.pts.map((p, i) =>
        <path key={i} d={`M${p.x} ${p.y} C ${p.x} ${p.y + 44}, ${flow.cx} ${flow.cy - 48}, ${flow.cx} ${flow.cy - 8}`} fill="none" stroke="oklch(0.52 0.16 268 / 0.35)" strokeWidth="1.5" />
        )}
          <path d={`M${flow.cx - 7} ${flow.cy - 12} L${flow.cx} ${flow.cy} L${flow.cx + 7} ${flow.cy - 12} Z`} fill="oklch(0.52 0.16 268)" />
        </svg>
      }
      <div className="la-osurface">
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
          <span style={{ display: "inline-flex", alignItems: "center", gap: 7, fontFamily: "monospace", fontSize: 12, color: "rgba(27,30,43,0.5)" }}>
            <span className="la-livedot" />your-business · live
          </span>
          <span style={{ display: "inline-flex", alignItems: "center", gap: 6, fontFamily: "monospace", fontSize: 11, fontWeight: 600, color: LA.accent, background: LA.accentSoft, padding: "4px 9px", borderRadius: 100 }}>
            <span className="la-refreshdot" />self-refreshing
          </span>
        </div>
        <div style={{ display: "flex", flexDirection: "column" }}>
          {rows.map((r, i) => {
            const tone = r.tone === "risk" ? { c: LA.danger, bg: "oklch(0.55 0.18 25 / 0.1)" } : r.tone === "ok" ? { c: green, bg: "oklch(0.6 0.13 155 / 0.12)" } : { c: "rgba(27,30,43,0.5)", bg: "transparent" };
            return (
              <div key={r.t} className="la-osrow" style={{ display: "flex", alignItems: "center", gap: 12, padding: "14px 2px", borderTop: i ? `1px solid ${LA.line}` : "none", animationDelay: `${1 + i * 2.4}s` }}>
                <span style={{ width: 8, height: 8, borderRadius: 99, background: tone.c, flexShrink: 0, opacity: r.tone === "mute" ? 0.5 : 1 }} />
                <span style={{ display: "flex", flexDirection: "column", minWidth: 0, flex: 1 }}>
                  <span style={{ fontSize: 14.5, fontWeight: 600, color: LA.ink, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{r.t}{r.s && <span style={{ color: LA.muted, fontWeight: 500 }}> — {r.s}</span>}</span>
                </span>
                <span className="la-ostag" style={{ display: "inline-flex", alignItems: "center", gap: 5, fontFamily: "monospace", fontSize: 11.5, fontWeight: 600, color: tone.c, background: tone.bg, padding: "4px 9px", borderRadius: 7, flexShrink: 0, whiteSpace: "nowrap" }}>
                  {r.tone === "ok" && <span style={{ fontSize: 12 }}>✓</span>}{r.tag}
                </span>
              </div>);

          })}
        </div>
      </div>
    </div>);

}

